/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnsajusteWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'TIPAJUNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &tipajuNome1.FromString(&GridStateDynamicFilter.Value) If not &tipajuNome1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Tipo", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Tipo", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&tipajuNome1) EndIf Case &DynamicFiltersSelector1 = !'AJUSLOCADESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &ajusLocaDescricao1.FromString(&GridStateDynamicFilter.Value) If not &ajusLocaDescricao1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Local", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Local", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&ajusLocaDescricao1) EndIf Case &DynamicFiltersSelector1 = !'AJUSCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &ajusCodigo1.FromString(&GridStateDynamicFilter.Value) If not &ajusCodigo1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Código", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &ajusCodigo1 EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'TIPAJUNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &tipajuNome2.FromString(&GridStateDynamicFilter.Value) If not &tipajuNome2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Tipo", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Tipo", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&tipajuNome2) EndIf Case &DynamicFiltersSelector2 = !'AJUSLOCADESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &ajusLocaDescricao2.FromString(&GridStateDynamicFilter.Value) If not &ajusLocaDescricao2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Local", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Local", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&ajusLocaDescricao2) EndIf Case &DynamicFiltersSelector2 = !'AJUSCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &ajusCodigo2.FromString(&GridStateDynamicFilter.Value) If not &ajusCodigo2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Código", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &ajusCodigo2 EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'TIPAJUNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &tipajuNome3.FromString(&GridStateDynamicFilter.Value) If not &tipajuNome3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Tipo", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Tipo", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&tipajuNome3) EndIf Case &DynamicFiltersSelector3 = !'AJUSLOCADESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &ajusLocaDescricao3.FromString(&GridStateDynamicFilter.Value) If not &ajusLocaDescricao3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Local", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Local", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&ajusLocaDescricao3) EndIf Case &DynamicFiltersSelector3 = !'AJUSCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &ajusCodigo3.FromString(&GridStateDynamicFilter.Value) If not &ajusCodigo3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Código", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &ajusCodigo3 EndIf EndCase EndIf EndIf EndIf If not (&TFajusCodigo.IsEmpty() AND &TFajusCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Código") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFajusCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFajusCodigo_To EndIf If not (&TFajusData.IsEmpty() AND &TFajusData_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Data") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &TFajusData WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &TFajusData_To EndIf If not (&TFtipajuCodigo_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Tipo Ajuste") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = &TFtipajuCodigo_SelDsc
Else If not (&TFtipajuCodigo.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Tipo Ajuste") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFtipajuCodigo) EndIf EndIf If not (&TFtipajuAcao_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Ação") &i = 1 For &TFtipajuAcao_Sel in &TFtipajuAcao_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += &TFtipajuAcao_Sel.EnumerationDescription() &i += 1 EndFor EndIf If not (&TFajusLocaCodigo_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Local") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = &TFajusLocaCodigo_SelDsc
Else If not (&TFajusLocaCodigo.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Local") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFajusLocaCodigo) EndIf EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnsajusteWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnsajusteWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsajuste order tipajuNome when &OrderedBy = 1 order ajusCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (ajusCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order ajusData when &OrderedBy = 3 AND &OrderedDsc = False order (ajusData) when &OrderedBy = 3 AND &OrderedDsc = True order tipajuCodigo when &OrderedBy = 4 AND &OrderedDsc = False order (tipajuCodigo) when &OrderedBy = 4 AND &OrderedDsc = True order tipajuAcao when &OrderedBy = 5 AND &OrderedDsc = False order (tipajuAcao) when &OrderedBy = 5 AND &OrderedDsc = True order ajusLocaCodigo when &OrderedBy = 6 AND &OrderedDsc = False order (ajusLocaCodigo) when &OrderedBy = 6 AND &OrderedDsc = True
using trnsajusteWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &tipajuNome1, &ajusLocaDescricao1, &ajusCodigo1, &DynamicFiltersEnabled2 , &DynamicFiltersSelector2, &DynamicFiltersOperator2, &tipajuNome2, &ajusLocaDescricao2, &ajusCodigo2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &tipajuNome3, &ajusLocaDescricao3, &ajusCodigo3, &TFajusCodigo , &TFajusCodigo_To, &TFajusData, &TFajusData_To, &TFtipajuCodigo, &TFtipajuCodigo_Sel, &TFtipajuAcao_Sels , &TFajusLocaCodigo, &TFajusLocaCodigo_Sel) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'ajusCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = ajusCodigo Case &ColumnsSelector_Column.ColumnName = !'ajusData' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Date = ajusData Case &ColumnsSelector_Column.ColumnName = !'tipajuCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(tipajuNome) Case &ColumnsSelector_Column.ColumnName = !'tipajuAcao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = tipajuAcao.EnumerationDescription() Case &ColumnsSelector_Column.ColumnName = !'ajusLocaCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(locDescricao) EndCase &VisibleColumnCount += 1 EndIf EndFor If ajusStatus = 'C' &ExcelDocument.Cells(&CellRow, &FirstColumn, 1, &VisibleColumnCount).Color = RGB(251,110,82) EndIf
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnsajusteWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"ajusCodigo", '', !'Código', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"ajusData", '', !'Data', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"tipajuCodigo", '', !'Tipo Ajuste', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"tipajuAcao", '', !'Ação', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"ajusLocaCodigo", '', !'Local', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnsajusteWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsajusteWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsajusteWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsajusteWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFAJUSCODIGO" &TFajusCodigo.FromString(&GridStateFilterValue.Value) &TFajusCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFAJUSDATA" &TFajusData.FromString(&GridStateFilterValue.Value) &TFajusData_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFTIPAJUCODIGO" &TFtipajuCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFTIPAJUCODIGO_SEL" &TFtipajuCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFTIPAJUACAO_SEL" &TFtipajuAcao_SelsJson = &GridStateFilterValue.Value &TFtipajuAcao_Sels.FromJson(&TFtipajuAcao_SelsJson) Case &GridStateFilterValue.Name = !"TFAJUSLOCACODIGO" &TFajusLocaCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAJUSLOCACODIGO_SEL" &TFajusLocaCodigo_Sel.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforeWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

parm(out:&Filename, out:&ErrorMessage);

	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
